		    const running=jobId?null:[...store.jobs.values()].find(e=>e.packId===pack.id&&e.input?.selection?.sourceId===pack.sourceId);
		    React.useEffect(()=>{if(running)setJob(jobKey,running.jobId);},[running?.jobId]);
