			const parts = [];
			if (assets.sprites) parts.push(assets.sprites + " 张立绘");
			if (assets.backgrounds) parts.push(assets.backgrounds + " 张背景");
			if (assets.avatars) parts.push(assets.avatars + " 个头像");
