			const unmatched = assets.unmatched || [];
			if (unmatched.length) notes.push(unmatched.length + " 个表情名未识别（" + unmatched.slice(0, 5).join("、") + (unmatched.length > 5 ? "…" : "") + "），已保留，导出 CHARX 时写回");
