		            const authored = { ref: entry.row.ref, identity: JSON.stringify([DICE_SE_PACK, value.media]), gainDb, ...(typeof value.volume === "number" ? { volume: value.volume } : {}), ...(value.loudness ? { loudness: value.loudness } : {}) };
		            entry.plays++;
