		        col += uDustColor * (dust(150.0, 0.55, 0.0, u, lr, r0) + 0.8 * dust(340.0, 0.9, 17.0, u, lr, r0)) * cluster * uDust * smoothstep(0.012, 0.06, r0) * exp(-r0 * uDustSpread);
